1904	  const removeCustomCategory = (name: string) => {
1905	    const trimmed = (name || '').trim();
1906	    if (!trimmed) return;
1907	    const hasItems = itens.some(
1908	      (i) => (i.category || 'Geral').trim() === trimmed,
