1935	  const finalizarPicking = async () => {
1936	    if (finalizando) return; // Guard local contra duplo-clique
1937	    if (!requisicaoId) return;
1938	
1939	    const itensNaoColetados = itens.filter(
1940	      (item) => !(String(item.quantidade_enviada || '').trim() !== ''),
1941	    );
1942	    if (itensNaoColetados.length > 0) {
1943	      toast({
1944	        title: 'Atenção',
1945	        description: `Ainda há ${itensNaoColetados.length} itens não coletados.`,
1946	        variant: 'destructive',
1947	      });
1948	      return;
1949	    }
1950	
1951	    let statusReserved = false;
1952	    try {
1953	      setFinalizando(true);
1954	
1955	      // === GUARD DE RACE CONDITION ===
1956	      // Estratégia: fazer o UPDATE atômico em_progresso -> finalizada ANTES de deduzir estoque.
1957	      // O PostgreSQL serializa UPDATEs concorrentes na mesma linha, então apenas uma sessão
1958	      // conseguirá afetar a linha; as demais receberão 0 rows e abortarão.
1959	      // Se a dedução posterior falhar, revertemos o status no bloco catch.
1960	      const { data: reserveData, error: reserveError } = await supabase
1961	        .from('requisicoes' as any)
1962	        .update({ status: 'finalizada' })
1963	        .eq('id', requisicaoId)
1964	        .eq('status', 'em_progresso')
1965	        .select('id');
1966	
1967	      if (reserveError) throw reserveError;
1968	
1969	      const affected =
1970	        reserveData && Array.isArray(reserveData) ? reserveData.length : 0;
1971	
1972	      if (affected === 0) {
1973	        // Outra sessão já finalizou, ou o status não era 'em_progresso'.
1974	        // Verifica o status atual para dar feedback preciso.
1975	        const { data: currentReq } = await supabase
1976	          .from('requisicoes' as any)
1977	          .select('status')
1978	          .eq('id', requisicaoId)
1979	          .single();
1980	
1981	        const currentStatus = (currentReq as { status?: string } | null)?.status;
1982	        const normalizedCurrent = normalizeRequisicaoStatus(currentStatus);
1983	
1984	        if (normalizedCurrent === 'finalizada') {
1985	          toast({
1986	            title: 'Já finalizada',
1987	            description: 'Esta requisição já foi finalizada por outra sessão.',
1988	            variant: 'destructive',
1989	          });
1990	          navigate('/logistica');
1991	        } else {
1992	          toast({
1993	            title: 'Não foi possível finalizar',
1994	            description: `Status inesperado: ${currentStatus || 'desconhecido'}. Recarregue a página.`,
1995	            variant: 'destructive',
1996	          });
1997	        }
1998	        return;
1999	      }
2000	
2001	      statusReserved = true;
2002	
2003	      // Picking é apenas separação: NÃO movimenta estoque nem contagem.
2004	      // A baixa/entrada de estoque ocorre via bip (Scanner) e na conferência,
2005	      // nunca aqui na finalização da separação.
2006	
2007	      // 2. Status da requisição já foi atualizado atomicamente no início (guard).
2008	      //    Apenas registra a conclusão no Control Tower.
2009	      await logSeparationCompleted(
2010	        Number(requisicaoId),
2011	        myProfileName,
2012	        reqInfo?.loja_solicitante || 'Loja',
2013	        itens.length,
2014	      );
2015	
2016	      // 3. Log user event (broadcast to other users in real-time)
2017	      if (user) {
2018	        const nomeUser = myProfileName;
2019	        channelRef.current?.send({
2020	          type: 'broadcast',
2021	          event: 'user_event',
2022	          payload: { text: `${nomeUser} finalizou a separação` },
2023	        });
2024	      }
2025	
2026	      toast({
2027	        title: 'Sucesso',
2028	        description: 'Separação finalizada.',
2029	      });
2030	      navigate('/logistica');
2031	    } catch (error) {
2032	      handleError(error, { domain: 'requisicoes', operation: 'finalizarSeparacao', showToast: false });
2033	
2034	      // Se o status foi reservado (reverteu para 'finalizada') mas a dedução de estoque falhou,
2035	      // tenta reverter para 'em_progresso' para que a separação possa ser retomada.
2036	      if (statusReserved) {
2037	        try {
2038	          await supabase
2039	            .from('requisicoes' as any)
2040	            .update({ status: 'em_progresso' })
2041	            .eq('id', requisicaoId)
2042	            .eq('status', 'finalizada');
2043	          toast({
2044	            title: 'Erro ao finalizar',
2045	            description: 'O processo foi revertido. Tente finalizar novamente.',
2046	            variant: 'destructive',
2047	          });
2048	        } catch (revertErr) {
2049	          handleError(revertErr, { domain: 'requisicoes', operation: 'finalizarSeparacaoRevert', showToast: false });
2050	          toast({
2051	            title: 'Erro grave',
2052	            description:
2053	              'A finalização falhou e a reversão do status também. Contate o suporte imediatamente.',
2054	            variant: 'destructive',
2055	          });
2056	        }
2057	      } else {
2058	        toast({
2059	          title: 'Erro',
2060	          description: 'Erro ao processar finalização.',
2061	          variant: 'destructive',
2062	        });
2063	      }
2064	    } finally {
2065	      setFinalizando(false);
2066	    }
2067	  };
2068	
2069	  const calcularProgresso = () => {
2070	    if (itens.length === 0) return 0;
2071	
2072	    // Progresso ponderado pela quantidade solicitada de cada item.
2073	    // Itens com quantidade 0 (ou inválida) contam como binário (coletado / não coletado)
2074	    // para não distorcer o cálculo.
2075	    let totalPeso = 0;
2076	    let totalEnviadoPeso = 0;
2077	
2078	    for (const item of itens) {
2079	      const solicitada = Number(item.quantidade) || 0;
2080	      const enviada = parseFloat(item.quantidade_enviada || '0');
2081	      const enviadaValida = Number.isFinite(enviada) && enviada > 0 ? enviada : 0;
2082	
2083	      if (solicitada > 0) {
2084	        totalPeso += solicitada;
2085	        // Clampa entre 0 e solicitada para não passar de 100% por item
2086	        totalEnviadoPeso += Math.min(enviadaValida, solicitada);
2087	      } else {
2088	        // Fallback binário: 1 ponto por item, 1 se marcado
2089	        totalPeso += 1;
2090	        if (String(item.quantidade_enviada || '').trim() !== '') {
2091	          totalEnviadoPeso += 1;
2092	        }
2093	      }
2094	    }
2095	
2096	    if (totalPeso === 0) return 0;
2097	    return Math.round((totalEnviadoPeso / totalPeso) * 100);
2098	  };
