// eslint-disable-next-line @typescript-eslint/no-explicit-any
const makeChainable = (table: string): any => {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const c: any = {
    select: vi.fn(() => c),
    eq: vi.fn(() => c),
    order: vi.fn(() => c),
    limit: vi.fn(() => c),
    in: vi.fn(() => c),
    not: vi.fn(() => c),
    ilike: vi.fn(() => c),
    or: vi.fn(() => c),
    gt: vi.fn(() => c),
    gte: vi.fn(() => c),
    lte: vi.fn(() => c),
    update: vi.fn(() => c),
    insert: vi.fn(() => c),
    delete: vi.fn(() => c),
    maybeSingle: vi.fn(() => Promise.resolve({ data: null, error: null })),
    single: vi.fn(() =>
      Promise.resolve({
        data: table === 'requisicoes' ? mockReqInfo : mockItensColetados[0],
        error: null,
      }),
    ),
    then: (resolve: (v: { data: unknown; error: null }) => void) => {
      if (table === 'requisicoes')
        return resolve({ data: mockReqInfo, error: null });
      if (table === 'requisicoes_itens')
        return resolve({ data: mockItensColetados, error: null });
      if (table === 'profiles')
        return resolve({
          data: { nome: 'Operador Teste', username: 'operador' },
          error: null,
        });
      return resolve({ data: [], error: null });
    },
  };
  return c;
};

/** Configura supabase.from + channel + rpc conforme cenário. */
const setupSupabaseMock = ({
  rpcResult,
}: {
  rpcResult: { data: unknown; error: null | { message: string } };
}) => {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  (supabase.from as any).mockImplementation((table: string) => {
    const c = makeChainable(table);
    // UPDATE atômico de status: retornar 1 row para simular sucesso de reserva.
    if (table === 'requisicoes') {
      c.update = vi.fn(() => {
        const upChain = { ...c };
        upChain.eq = vi.fn(() => upChain);
        upChain.select = vi.fn(() =>
          Promise.resolve({ data: [{ id: 123 }], error: null }),
        );
        return upChain;
      });
    }
    return c;
  });
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  (supabase.channel as any).mockReturnValue(mockChannel);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  (supabase.rpc as any).mockResolvedValue(rpcResult);
};

const renderComponent = () =>
  render(
    <BrowserRouter>
      <PaginaPicking />
    </BrowserRouter>,
  );

/** Aguarda o carregamento inicial do componente. */
const waitForLoad = () =>
  waitFor(() => expect(screen.getByText('Brownie')).toBeInTheDocument(), {
    timeout: 5000,
  });

/** Clica no botão Finalizar (habilitado). */
const clickFinalizar = async () => {
  const btn = screen.queryByRole('button', { name: /finalizar/i });
  if (!btn) throw new Error('Botão Finalizar não encontrado');
  await act(async () => {
    fireEvent.click(btn);
  });
};

// ── suíte ───────────────────────────────────────────────────────────────────

describe('finalizarPicking() — integração dar_saida_requisicao', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    (routerDom.useParams as typeof routerDom.useParams & { mockReturnValue: (v: unknown) => void })
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      .mockReturnValue({ requisicaoId: '123' } as any);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    (routerDom.useNavigate as any).mockReturnValue(mockNavigate);
  });

  it('1. chama dar_saida_requisicao com p_requisicao_id correto após reserva de status', async () => {
    setupSupabaseMock({
      rpcResult: {
        data: { ok: true, requisicao_id: 123, etiquetas_processadas: 3, total_quantidade: 9, ja_processadas: 0, alertas: [] },
        error: null,
      },
    });

    renderComponent();
    await waitForLoad();
    await clickFinalizar();

    await waitFor(() => {
      expect(supabase.rpc).toHaveBeenCalledWith('dar_saida_requisicao', {
        p_requisicao_id: 123,
      });
    });
  });

  it('2. exibe toast de warning quando alertas é não-vazio', async () => {
    setupSupabaseMock({
      rpcResult: {
        data: {
          ok: true,
          requisicao_id: 123,
          etiquetas_processadas: 2,
          total_quantidade: 4,
          ja_processadas: 0,
          alertas: [{ uid: 'abc', motivo: 'saldo_insuficiente' }],
        },
        error: null,
      },
    });

    renderComponent();
    await waitForLoad();
    await clickFinalizar();

    await waitFor(() => {
      // Deve ter chamado toast de sucesso E toast de warning (destructive)
      const toastCalls = mockToast.mock.calls;
      const warningCall = toastCalls.find(
        ([arg]: [{ variant?: string; title?: string }]) => arg?.variant === 'destructive' && /saldo insuficiente/i.test(arg?.description ?? ''),
      );
      expect(warningCall).toBeDefined();
    });
  });

  it('3. quando RPC falha, status reverte para em_progresso e navigate NÃO é chamado', async () => {
    setupSupabaseMock({
      rpcResult: {
        data: null,
        error: { message: 'connection timeout' },
      },
    });

    renderComponent();
    await waitForLoad();
    await clickFinalizar();

    await waitFor(() => {
      // navigate('/logistica') NÃO deve ter sido chamado
      expect(mockNavigate).not.toHaveBeenCalledWith('/logistica');
    });

    // O UPDATE de rollback (em_progresso) deve ter sido tentado
    await waitFor(() => {
      // supabase.from('requisicoes').update() é chamado duas vezes:
      //   1ª: reserva → status='finalizada'
      //   2ª: rollback → status='em_progresso'
      const fromCalls = (supabase.from as ReturnType<typeof vi.fn>).mock.calls;
      const reqCalls = fromCalls.filter(([t]: [string]) => t === 'requisicoes');
      expect(reqCalls.length).toBeGreaterThanOrEqual(2);
    });
  });
});

